URL='http://127.0.0.1:3304/tests/alunix-r8/runs/V3d/index.html'
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        pg=await b.new_page(viewport={'width':1440,'height':900})
        await pg.goto(URL, wait_until='load')
        await pg.wait_for_timeout(1000)
        data = await pg.evaluate('''() => {
          const calyxFig = document.querySelector('.calyx-fig');
          const giant = document.getElementById('giant-section');
          const thesis = document.querySelector('.panel-thesis');
          return {calyxFig: calyxFig.getBoundingClientRect(), giant: giant.getBoundingClientRect(), thesis: thesis.getBoundingClientRect()};
        }''')
        print('layout', data)
        for y in range(3300, 3900, 50):
            await pg.evaluate(f'window.scrollTo(0,{y})')
            await pg.wait_for_timeout(300)
            d2 = await pg.evaluate('''() => {
              const calyxFig = document.querySelector('.calyx-fig');
              const thesis = document.querySelector('.panel-thesis');
              const giant = document.getElementById('giant-section');
              return {calyxVis: (calyxFig.getBoundingClientRect().top < 900 && calyxFig.getBoundingClientRect().bottom > 0),
                      thesisVis: (thesis.getBoundingClientRect().top < 900 && thesis.getBoundingClientRect().bottom > 0),
                      giantWidthPct: Math.round(1000*giant.getBoundingClientRect().width/1440)/10};
            }''')
            print(y, d2)
        await b.close()
asyncio.run(main())
"

