import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8791/tests/alunix-r8/runs/V3d/index.html"
WIDTHS = [320, 375, 390, 768, 1024, 1280, 1440]

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        for w in WIDTHS:
            pg = await browser.new_page(viewport={"width": w, "height": 900})
            await pg.goto(URL, wait_until="load", timeout=60000)
            await pg.wait_for_timeout(600)
            data = await pg.evaluate('''() => {
              const docW = document.documentElement.scrollWidth;
              const vw = window.innerWidth;
              let worst = null;
              document.querySelectorAll('body *').forEach(el => {
                const r = el.getBoundingClientRect();
                if (r.right > vw + 1) {
                  if (!worst || r.right > worst.right) worst = {tag: el.tagName, cls: el.className.toString().slice(0,40), right: Math.round(r.right)};
                }
              });
              return {docScrollWidth: docW, viewportWidth: vw, overflow: docW > vw + 1, worst};
            }''')
            print(w, data)
            await pg.close()
        await browser.close()

asyncio.run(main())

