import asyncio
from playwright.async_api import async_playwright

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":390,"height":844})
        for attempt in range(5):
            try:
                await pg.goto("http://127.0.0.1:8791/tests/alunix-r8/runs/V3d/index.html", wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt==4: raise
        await pg.wait_for_timeout(500)
        for y in [7422, 7950, 8460, 8622, 9150, 9600]:
            await pg.evaluate(f"window.scrollTo(0,{y})")
            await pg.wait_for_timeout(400)
            data = await pg.evaluate('''() => {
              const stick = document.querySelector('.process-stick');
              const sr = stick.getBoundingClientRect();
              const cs = getComputedStyle(stick);
              return {
                stickTop: Math.round(sr.top), stickBottom: Math.round(sr.bottom),
                position: cs.position,
              };
            }''')
            print(y, data)
        await browser.close()

asyncio.run(main())

